void main() {
  TimesTwo timetwo = TimesTwo(5);
  print(timetwo.calculate());

  TimeFour time = TimeFour(5);
  print(time.calculate());


}

class TimesTwo {
  final int number;

  TimesTwo(
    this.number,
  );

  int calculate() {
    return number * 2;
  }
}

class TimeFour extends TimesTwo {
  TimeFour(
    int number,
  ) : super(number);

  @override
  int calculate(){
    return super.number * 4;
  }
}




