class Employee{
  //static은 instance에 귀속되지 않고 class에 귀속된다.
  //알바생이 일하고 있는 건물

  static String? buling;

  String name;

  Employee(
    this.name,
  );

  void printNameAndBuilding(){
    print('제이름은 $name. $buling 건물에서 근무하고 있습니다.');

  }

  static void printBuilding(){
      print('저는 $buling 건물에서 근무중입니다.,');
    }
}


void main() {
